    "statistics": {
      "id": "statistics",
      "title": "Descriptive & Inferential Statistics",
      "category": "data-science",
      "icon": "📊",
      "badge": "Math & AI",
      "subtitle": "Measures of central tendency, dispersion, normal distribution, IQR & hypothesis tests",
      "groups": [
        {
          "groupTitle": "Central Tendency & Dispersion",
          "items": [
            {
              "syntax": "Mean = sum(x) / N",
              "desc": "Arithmetic average (sensitive to extreme outliers)"
            },
            {
              "syntax": "Median = Middle value in sorted dataset (50th percentile)",
              "desc": "Robust central tendency measure unaffected by skew"
            },
            {
              "syntax": "Variance (s²) = sum((x - mean)²) / (N - 1)",
              "desc": "Sample dispersion around mean"
            },
            {
              "syntax": "Std Dev (s) = sqrt(Variance)",
              "desc": "Standard deviation in original measurement units"
            }
          ]
        },
        {
          "groupTitle": "Distribution & Outlier Bounds",
          "items": [
            {
              "syntax": "Z-score = (X - μ) / σ",
              "desc": "Number of standard deviations from the population mean"
            },
            {
              "syntax": "Empirical Rule: 68% within ±1σ, 95% within ±2σ, 99.7% within ±3σ",
              "desc": "Normal distribution probability boundaries"
            },
            {
              "syntax": "IQR = Q3 - Q1; Lower = Q1 - 1.5*IQR, Upper = Q3 + 1.5*IQR",
              "desc": "Tukey's fences method for detecting data outliers"
            }
          ]
        },
        {
          "groupTitle": "Inferential Statistics & Hypothesis Testing",
          "items": [
            {
              "syntax": "Null Hypothesis (H0): No effect / difference; Alt (H1): Significant effect",
              "desc": "Standard hypothesis formulation"
            },
            {
              "syntax": "p-value < α (typically 0.05) -> Reject H0",
              "desc": "Statistical significance decision rule"
            },
            {
              "syntax": "Type I Error (α): False Positive; Type II Error (β): False Negative",
              "desc": "Hypothesis testing error classifications"
            },
            {
              "syntax": "t = (mean1 - mean2) / sqrt(s1²/n1 + s2²/n2)",
              "desc": "Two-sample independent Student's t-statistic"
            }
          ]
        }
      ]
    },
